    topic: 'Geometry (Pythagorean theorem)',
    build: () => {
      const triples = [
        [3, 4, 5],
        [6, 8, 10],
        [5, 12, 13],
        [8, 15, 17],
        [7, 24, 25],
        [9, 12, 15]
      ];
      const [legA, legB, hyp] = choice(triples);
      const k = randInt(1, 4);
      const a = legA * k;
      const b = legB * k;
      const h = hyp * k;
      const askHyp = choice([true, false]);
      if (askHyp) {
        return {
          type: 'numeric',
          prompt: `A support strut forms a right triangle with legs of ${a} m and ${b} m. What is the length of the hypotenuse, in meters?`,
          answer: String(h),
          explanation: `√(${a}² + ${b}²) = √(${a * a} + ${b * b}) = √${a * a + b * b} = ${h} meters.`,
          xp: 10
        };
      }
      return {
        type: 'numeric',
        prompt: `A support cable (hypotenuse) is ${h} m, and one leg of the right triangle it forms is ${a} m. What is the length of the other leg, in meters?`,
        answer: String(b),
        explanation: `√(${h}² − ${a}²) = √(${h * h} − ${a * a}) = √${h * h - a * a} = ${b} meters.`,
        xp: 10
      };
    }
